301	            </div>
302	          ))}
303	        </div>
304	      </div>
305	    </div>
306	  );
307	};
308	
309	// Mesmo padrão visual/comportamento de src/pages/customer-profile/index.jsx:
310	// avatar circular com upload instantâneo (salva na hora, sem passar pelo form),
311	// campos de dados num card com header ícone+label, senha via CredenciaisForm.
