641	  const [ocorrencia, setOcorrencia] = useState(null); // { pedido, tipo }
642	  const [salvandoOcorrencia, setSalvandoOcorrencia] = useState(false);
643	  const [gpsAtivo, setGpsAtivo] = useState(false);
644	  const [gpsErro, setGpsErro] = useState(null);
645	  const gpsRef = useRef(null);
646	  const prevDisponiveisCount = useRef(0);
647	  const tocarSom = useNotificacaoSonora('motoboy');
648	
649	  const carregarAfiliacoes = useCallback(async () => {
650	    try {
651	      const d = await getMinhasAfiliacoes();
652	      const lista = d.afiliacoes ?? [];
653	      setAfiliacoes(lista);
654	      const aceitos = lista.filter((a) => a.status === 'aceito');
655	      setEstabelecimentoAtivo((atual) => atual ?? aceitos[0]?.restaurant?.id ?? null);
656	    } catch {}
657	  }, []);
658	
659	  const carregarDados = useCallback(async () => {
660	    try {
661	      const [infoData, pedidosData] = await Promise.all([getMe(), getMeusPedidos()]);
662	      setMe(infoData);
663	      setPedidos(pedidosData.pedidos ?? []);
664	      setErro(null);
665	    } catch (e) {
666	      setErro(e.message);
667	    } finally {
668	      setLoading(false);
669	    }
670	  }, []);
671	
672	  useEffect(() => {
673	    carregarDados();
674	    carregarAfiliacoes();
675	    const interval = setInterval(() => { carregarDados(); carregarAfiliacoes(); }, 30000);
676	    return () => clearInterval(interval);
677	  }, [carregarDados, carregarAfiliacoes]);
