684	        const novos = d.pedidos ?? [];
685	        if (novos.length > prevDisponiveisCount.current) tocarSom();
686	        prevDisponiveisCount.current = novos.length;
687	        setDisponiveis(novos);
688	      } catch {}
689	    };
690	    carregarDisponiveis();
691	    const id = setInterval(carregarDisponiveis, 10000);
692	    return () => clearInterval(id);
